$(() => {
  // 在页面加载完成后立即执行

  // 监听消息接收事件
  eventOn(tavern_events.MESSAGE_RECEIVED, () => {
    // 获取聊天记录中最新的一条消息
    const lastMessage = SillyTavern.chat[SillyTavern.chat.length - 1];

    // 如果这条消息存在且内容存在
    if (lastMessage && lastMessage.mes) {
      // 对消息内容执行标签间插入空行的处理
      lastMessage.mes = fixXmlSpacing(lastMessage.mes);
    }
  });

  // 定义处理函数，用于在 </xxx> 与 <yyy> 之间插入空行
  function fixXmlSpacing(text) {
    // 如果输入不是字符串，直接返回原内容
    if (!text || typeof text !== 'string') return text;

    // 使用正则查找形如 </标签>\n<标签> 的结构，并在中间插入一个空行
    return text.replace(
      /(^|\n)(<\/[^>]+>)\n(<[^\/][^>]+>)/gm,
      (match, before, closingTag, openingTag) => {
        // 返回替换后的格式：前面 + 闭合标签 + 空行 + 开标签
        return `${before}${closingTag}\n\n${openingTag}`;
      }
    );
  }
});

